 "content": "def transform(grid):
    cells = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    if not cells:
        return [row[:] for row in grid]
    bottom = max(r for r, c, v in cells)
    out = [[0] * len(grid[0]) for _ in grid]
    for r, c, v in cells:
        nc = c - (bottom - r)
        if 0 <= nc < len(grid[0]):
            out[r][nc] = v
    return out
